import re

_DATE_PATTERN = re.compile(r"([0-9]{2})-([0-9]{2})-([0-9]{4})")

_MONTHS_WITH_31_DAYS = {1, 3, 5, 7, 8, 10, 12}
_MONTHS_WITH_30_DAYS = {4, 6, 9, 11}
_FEBRUARY = 2


def valid_date(date):
    """Validate a date string and return True if it is valid, otherwise False.

    Rule 4 lists both "dd-mm-yyyy" and "mm-dd-yyyy", which contradict each
    other. The examples settle it: '15-01-2012' is invalid, which only holds
    if the first field is the month. So the format used here is mm-dd-yyyy,
    with '-' as the separator and zero-padded numeric fields.

    Rules enforced:
      1. The string is not empty.
      2. Days are 1-31 for months 1,3,5,7,8,10,12; 1-30 for months 4,6,9,11;
         and 1-29 for month 2. Leap years are not checked, per the spec.
      3. Months are 1-12.
      4. The format is mm-dd-yyyy.
    """
    if not isinstance(date, str):
        return False

    date = date.strip()
    if not date:
        return False

    match = _DATE_PATTERN.fullmatch(date)
    if match is None:
        return False

    month, day, _year = (int(part) for part in match.groups())

    if month in _MONTHS_WITH_31_DAYS:
        max_day = 31
    elif month in _MONTHS_WITH_30_DAYS:
        max_day = 30
    elif month == _FEBRUARY:
        max_day = 29
    else:
        return False  # Month is outside 1-12.

    return 1 <= day <= max_day
